#!/usr/bin/env node
// docs/STATUS.md's inventory line must still describe the repository.
//
//   node scripts/check-status-figures.mjs
//   node scripts/check-status-figures.mjs --self-test
//
// WHY THIS IS NOT A BYTE-EQUALITY SYNC GATE, which is what I tried first and had
// to take back. `docs/STATUS.md` is generated by `scripts/status-summary.mjs`, so
// it looks like the Postman collection, the evidence-coverage page and the SBOM —
// all of which ARE gated by "regenerate and diff". It is not the same shape, and
// two properties say so:
//
//   1. It embeds the HEAD short sha and branch, BY DESIGN. The generator's own
//      comment calls that the staleness tell: the file names the commit it
//      describes so a reader can check it against `git rev-parse --short HEAD`.
//      A regenerate-and-diff gate can therefore never pass — the commit that
//      adds the file changes HEAD, so the file can never equal its own
//      regeneration. I shipped exactly that gate and it was red on arrival.
//   2. The generator is slow (>120s here) and makes network calls (`git ls-remote`
//      to compare local and remote HEAD). Putting that on every push would buy
//      a flaky, expensive check for a file that is meant to be a snapshot.
//
// So this gates the part that actually rots: the INVENTORY FIGURES. They are pure
// counts over the working tree, they are cheap, they are offline, and they are what
// went stale — the line read 95 proof gates against a real 122, 8 E2E specs against
// 10, and 12 CI workflows against 16. Understating the work is the safe direction,
// which is precisely why nobody noticed for so long.
//
// The four counts below MIRROR scripts/status-summary.mjs exactly. If that
// generator's definitions change, this must change with them — a gate that counts
// differently from the thing it checks would report drift that is not there. The
// live-vendor lane count is therefore DERIVED FROM THE GENERATOR'S OWN LANE_ENV map
// rather than re-invented here, for exactly that reason.
//
// It was three counts until 2026-09-06, and the fourth is why this note exists: the
// LINE pattern captured `live-vendor lanes` in group 2 from the first version, and
// `parseStatus` returned groups 1, 3 and 4. A published figure was parsed and dropped,
// so it could say anything at all while the gate printed "the inventory line matches
// the tree".

import { readFileSync, readdirSync, existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const STATUS = join(repo, "docs/STATUS.md");

const GENERATOR = join(repo, "scripts/status-summary.mjs");
const E2E_README = join(repo, "scripts/src/e2e/README.md");
const SIGNALGRID_SKILL = join(repo, ".claude/skills/signalgrid/SKILL.md");
const COMPLETION_PLAN = join(repo, "docs/PRODUCT_COMPLETION_PLAN.md");

/**
 * docs/PRODUCT_COMPLETION_PLAN.md hand-quotes a 2026-08-10 census ("exactly 51"
 * connector families, "167 entries", "47 gates fire on deferred families") that no
 * gate can keep true and nobody maintains (BUILD_BACKLOG, census-figures row). Those
 * figures stay as history; what is held is the banner that says so. It must sit
 * above the first section, carry a date, and name a command that derives the live
 * numbers — a banner without the command tells the reader the figure is stale and
 * leaves them nowhere to go.
 */
export function hasSnapshotBanner(src) {
  // A banner inside an HTML comment is invisible to the reader it exists for.
  const visible = src.replace(/<!--[\s\S]*?-->/g, "");
  // "Above the first section" needs a first section: a document with no `## ` heading
  // would make the whole file the head, and a banner at the very bottom would pass.
  const parts = visible.split(/^## /m);
  if (parts.length < 2) return false;
  const m = parts[0].match(/^> \*\*Point-in-time snapshot \(census taken (\d{4}-\d{2}-\d{2})[^\n]*(?:\n>[^\n]*)*/m);
  if (!m) return false;
  const d = new Date(`${m[1]}T00:00:00Z`);
  if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== m[1]) return false;
  const text = m[0].replace(/\n>\s?/g, " ");
  return /`node scripts\/check-preflight-ci-parity\.mjs`/.test(text) && /\bNOT maintained\b/.test(text);
}

/**
 * Live test-count claims in the e2e README (plan row 148). It said the suite "has
 * since grown to 35", then "41 `test(` declarations", while `playwright test --list`
 * reported 53 — two of the specs generate tests in a loop, so even a careful hand
 * count of declarations undercounts. The section making the claim is the one whose
 * lesson is that a README describing a test's live state is a hand-maintained claim.
 * A number here that no gate reads has two stable states, absent or wrong, so this
 * gate holds it at absent: the README points at `--list` instead. A dated historical
 * snapshot in `N/N` form ("15/15 at that point") is not a live count and is allowed.
 */
const NUMBER_WORD =
  "(?:(?:twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)(?:-(?:one|two|three|four|five|six|seven|eight|nine))?|" +
  "one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|" +
  "seventeen|eighteen|nineteen|hundred|dozen)";
// A number (digits or words, not one half of an `N/N` snapshot) followed within three
// words by a test-ish noun, or "grown to N". Broad on purpose: the phrasing this gate
// has to stop is whichever one the next hand-count reaches for, not the last one used.
const COUNT_CLAIM = new RegExp(
  `(?<![\\w/])(?:\\d+|${NUMBER_WORD})(?![\\w/])(?:[\\s\\x60*(]+[\\w\\x60().:-]+){0,3}?[\\s\\x60*(]+` +
    `(?:e2e\\s+)?(?:tests?|specs?|spec\\s+files?|cases?|scenarios?|declarations?)\\b|\\bgrown\\s+to\\s+(?:\\d+|${NUMBER_WORD})\\b`,
  "gi",
);
export function e2eReadmeCountClaims(src) {
  return [...src.matchAll(COUNT_CLAIM)].map((m) => m[0]);
}

/**
 * A typed repository file count in the signalgrid skill (plan row 73). Its "Prefer
 * deleting to adding" rule said "With ~1,800 files" from 2026-08 until 2026-09-30,
 * while `git ls-files` counted 2,306, then 3,446, then 3,515 — the instruction every
 * agent loads described a repository half the size of the real one, and nothing read
 * the figure. Same two stable states as the e2e README, so the same answer: held at
 * absent. The skill points at `git ls-files | wc -l`. Digits only, with an optional
 * `~`/`about`/`over` and thousands separators; "thousands of tracked files" is prose,
 * not a count, and does not fire.
 */
// \p{Nd} rather than \d so full-width and other Unicode digits count too. Up to three
// qualifying words may stand between the figure and "files" ("3,515 Markdown and TS
// files"), and a magnitude word ("3.5 thousand files") is part of the figure.
const FILE_COUNT_CLAIM =
  /(?<![\p{L}\p{Nd}_/.:])~?\p{Nd}[\p{Nd},.]*(?:\s*(?:k|thousand|hundred))?\+?(?:\s+[\p{L}`*/-]+){0,3}?\s+files\b|\bfile\s+count\s*[:=]?\s*~?\p{Nd}[\p{Nd},.]*/giu;
export function skillFileCountClaims(src) {
  return [...src.matchAll(FILE_COUNT_CLAIM)].map((m) => m[0]);
}

/**
 * The live-vendor lane count, DERIVED the way the generator derives it: the keys of
 * `LANE_ENV` in scripts/status-summary.mjs, intersected with the scripts that actually
 * exist in package.json.
 *
 * WHY NOT just count `proof:live-*` in package.json. Because that is a DIFFERENT
 * number and the difference is the point: eight `proof:live-*` scripts exist, one
 * (`proof:live-idp`) runs in-process and is deliberately excluded, and three more are
 * not declared in LANE_ENV — so a naive count says 7 where the generator says 4, and
 * this gate would report drift that is not there against an honest page. A gate that
 * counts differently from the thing it checks manufactures its own findings.
 *
 * Fails CLOSED: if `LANE_ENV` cannot be found or yields no keys, the generator's shape
 * has changed and this returns null so the caller refuses rather than comparing against
 * a zero it invented.
 */
export function liveLaneCount(generatorSrc, pkgScripts) {
  const block = generatorSrc.match(/const LANE_ENV\s*=\s*\{([\s\S]*?)\n\};/);
  if (!block) return null;
  const keys = [...block[1].matchAll(/"(proof:[a-z0-9:-]+)"\s*:/g)].map((m) => m[1]);
  if (keys.length === 0) return null;
  return keys.filter((k) => k in (pkgScripts ?? {})).length;
}

/** Counts, defined identically to status-summary.mjs. */
function counts() {
  const pkg = JSON.parse(readFileSync(join(repo, "package.json"), "utf8"));
  const proofs = Object.keys(pkg.scripts ?? {}).filter((k) => k.startsWith("proof:")).length;
  const e2eDir = join(repo, "scripts/src/e2e");
  const specs = existsSync(e2eDir) ? readdirSync(e2eDir).filter((f) => f.endsWith(".spec.ts")).length : 0;
  const wfDir = join(repo, ".github/workflows");
  const workflows = existsSync(wfDir) ? readdirSync(wfDir).filter((f) => f.endsWith(".yml")).length : 0;
  const lanes = existsSync(GENERATOR) ? liveLaneCount(readFileSync(GENERATOR, "utf8"), pkg.scripts) : null;
  return { proofs, specs, workflows, lanes };
}

/** The one line in STATUS.md that carries the inventory. */
const LINE =
  /- proof gates: \*\*(\d+)\*\* · live-vendor lanes: \*\*(\d+)\*\* · browser E2E specs: \*\*(\d+)\*\* · CI workflows: \*\*(\d+)\*\*/;

function parseStatus(src) {
  const m = src.match(LINE);
  if (!m) return null;
  return { proofs: Number(m[1]), lanes: Number(m[2]), specs: Number(m[3]), workflows: Number(m[4]) };
}

/**
 * Every figure on the line, paired with the tree's own count. One row per field
 * `parseStatus` returns — the self-test asserts that, because the defect this gate
 * carried was a figure that was PARSED and never compared.
 */
export function figureRows(declared, real) {
  return [
    ["proof gates", declared.proofs, real.proofs],
    // Gated since 2026-09-06. The LINE pattern has always CAPTURED this figure and
    // parseStatus always dropped it, so one of the four numbers on the line was
    // read and thrown away while the gate reported "the inventory line matches the
    // tree" — a published figure free to rot behind a green check.
    ["live-vendor lanes", declared.lanes, real.lanes],
    ["browser E2E specs", declared.specs, real.specs],
    ["CI workflows", declared.workflows, real.workflows],
  ];
}

function main() {
  if (!existsSync(STATUS)) {
    console.error("✗ docs/STATUS.md does not exist — the status page is generated and must be committed.");
    process.exit(1);
  }
  const declared = parseStatus(readFileSync(STATUS, "utf8"));
  if (!declared) {
    console.error(
      "✗ docs/STATUS.md has no inventory line this gate can read.\n" +
        "  Either the generator's format changed (update the LINE pattern here to match), or the\n" +
        "  line was removed. A gate that silently stops finding its subject is worse than no gate.",
    );
    process.exit(1);
  }
  const real = counts();
  if (real.lanes === null) {
    console.error(
      "\u2717 the live-vendor lane count could not be derived from scripts/status-summary.mjs\n" +
        "  (its LANE_ENV map was not found, or parsed to no keys). That figure is PUBLISHED on the\n" +
        "  status page, so refusing is the only honest answer: comparing it against a count this gate\n" +
        "  invented would be worse than not checking it.",
    );
    process.exit(1);
  }
  const rows = figureRows(declared, real);

  console.log("STATUS.md inventory:");
  for (const [label, d, r] of rows) console.log(`  ${d === r ? "ok  " : "DRIFT"} — ${label}: says ${d}, repo has ${r}`);

  const drifted = rows.filter(([, d, r]) => d !== r);
  if (drifted.length) {
    console.error(
      `\nSTATUS.md figure gate FAILED — ${drifted.length} figure(s) no longer describe the repository.` +
        `\n  Regenerate with \`pnpm run status:write\` and commit.` +
        `\n  These are counts of what exists; a status page that understates the work still misdescribes it.\n`,
    );
    process.exit(1);
  }
  const claims = existsSync(E2E_README) ? e2eReadmeCountClaims(readFileSync(E2E_README, "utf8")) : [];
  if (claims.length) {
    console.error(
      `\nscripts/src/e2e/README.md types a live test count (${claims.map((c) => `"${c}"`).join(", ")}).` +
        `\n  No gate can keep that true; point at \`playwright test --list\` instead (plan row 148).\n`,
    );
    process.exit(1);
  }
  console.log("  ok   — scripts/src/e2e/README.md types no live test count (it points at --list)");
  if (!existsSync(SIGNALGRID_SKILL)) {
    console.error("\n.claude/skills/signalgrid/SKILL.md is missing — this gate cannot read what it guards; refusing.\n");
    process.exit(1);
  }
  const fileClaims = skillFileCountClaims(readFileSync(SIGNALGRID_SKILL, "utf8"));
  if (fileClaims.length) {
    console.error(
      `\n.claude/skills/signalgrid/SKILL.md types a repository file count (${fileClaims.map((c) => `"${c}"`).join(", ")}).` +
        `\n  No gate can keep that true; point at \`git ls-files | wc -l\` instead (plan row 73).\n`,
    );
    process.exit(1);
  }
  console.log("  ok   — .claude/skills/signalgrid/SKILL.md types no repository file count (it points at git ls-files)");
  if (!existsSync(COMPLETION_PLAN) || !hasSnapshotBanner(readFileSync(COMPLETION_PLAN, "utf8"))) {
    console.error(
      "\ndocs/PRODUCT_COMPLETION_PLAN.md has lost its dated point-in-time snapshot banner (or the file is gone)." +
        "\n  Its census figures are a 2026-08-10 hand count; without the banner they read as current measurements.\n",
    );
    process.exit(1);
  }
  console.log("  ok   — docs/PRODUCT_COMPLETION_PLAN.md carries its dated snapshot banner naming the live-count command");

  console.log("\nSTATUS.md figure gate passed — the inventory line matches the tree.");
  console.log("  NOT checked here: the commit sha STATUS.md names, or its gate verdicts. The sha is the");
  console.log("  file's own staleness tell and cannot be gated by regeneration (see the header).");
}

function selfTest() {
  const controls = [
    { name: "the inventory line is found in the real STATUS.md", run: () => parseStatus(readFileSync(STATUS, "utf8")) !== null },
    {
      name: "a line with different numbers parses to those numbers",
      run: () => {
        const p = parseStatus("- proof gates: **7** · live-vendor lanes: **1** · browser E2E specs: **2** · CI workflows: **3**");
        return p?.proofs === 7 && p.lanes === 1 && p.specs === 2 && p.workflows === 3;
      },
    },
    { name: "a file with no inventory line yields null (the gate fails loudly rather than passing)", run: () => parseStatus("# nothing here") === null },
    { name: "the counts are non-zero (an empty sweep would pass vacuously)", run: () => { const c = counts(); return c.proofs > 0 && c.specs > 0 && c.workflows > 0 && c.lanes > 0; } },
    {
      name: "EVERY figure the line carries is compared — none is parsed and dropped",
      run: () => {
        // The defect this pins: `live-vendor lanes` was captured and never compared.
        // Derived from the pattern itself, so a fifth figure added to the line and
        // forgotten fails here rather than riding along unchecked.
        const captured = LINE.source.match(/\(\\d\+\)/g)?.length ?? 0;
        const sample = parseStatus("- proof gates: **1** · live-vendor lanes: **1** · browser E2E specs: **1** · CI workflows: **1**");
        const parsed = Object.keys(sample ?? {}).length;
        const compared = figureRows(sample, { proofs: 1, lanes: 1, specs: 1, workflows: 1 }).length;
        return captured > 0 && captured === parsed && parsed === compared;
      },
    },
    {
      name: "the live-vendor lane count MIRRORS the generator's LANE_ENV, not a naive proof:live-* count",
      run: () => {
        const pkg = JSON.parse(readFileSync(join(repo, "package.json"), "utf8"));
        const naive = Object.keys(pkg.scripts ?? {}).filter((k) => k.startsWith("proof:live-")).length;
        const mirrored = liveLaneCount(readFileSync(GENERATOR, "utf8"), pkg.scripts);
        // They differ today (7 vs 4). If they ever stop differing the check still holds;
        // what must never happen is this gate using the naive number.
        return mirrored !== null && mirrored > 0 && mirrored <= naive;
      },
    },
    {
      name: "a generator whose LANE_ENV cannot be parsed yields null, so the gate REFUSES rather than comparing against 0",
      run: () => liveLaneCount("const OTHER = { a: 1 };", { "proof:live-edr": "x" }) === null && liveLaneCount("const LANE_ENV = {\n};", {}) === null,
    },
    {
      name: "the e2e README's retired count phrasings are caught, and a dated N/N snapshot is not",
      run: () =>
        e2eReadmeCountClaims("the suite has since grown to 35").length === 1 &&
        e2eReadmeCountClaims("41 `test(` declarations across 10 spec files").length === 2 &&
        e2eReadmeCountClaims("Total: 53 tests in 10 files").length === 1 &&
        e2eReadmeCountClaims("green — 15/15 **at that point**").length === 0 &&
        ["53 e2e tests", "53 Playwright tests", "fifty-three tests", "41 cases", "Forty-one `test(` declarations"].every(
          (x) => e2eReadmeCountClaims(x).length === 1,
        ),
    },
    {
      name: "the real e2e README types no live count",
      run: () => e2eReadmeCountClaims(readFileSync(E2E_README, "utf8")).length === 0,
    },
    {
      name: "the skill's retired file-count phrasings are caught, and prose without a count is not",
      run: () =>
        ["With ~1,800 files, 144", "3515 files", "about 3,446 tracked files", "~3,500+ files", "file count: 3,515",
          "3.5 thousand files", "3,515 Markdown and TS files", "\uFF13\uFF15\uFF11\uFF15 files"].every((x) => skillFileCountClaims(x).length === 1) &&
        skillFileCountClaims("With thousands of tracked files (`git ls-files | wc -l` counts them)").length === 0 &&
        skillFileCountClaims("144 `proof:*` scripts").length === 0 &&
        skillFileCountClaims("see SKILL.md:205 files").length === 0,
    },
    {
      name: "the real signalgrid skill types no repository file count",
      run: () => skillFileCountClaims(readFileSync(SIGNALGRID_SKILL, "utf8")).length === 0,
    },
    {
      name: "the completion plan's snapshot banner is found, and a missing, undated, command-less or buried one is not",
      run: () => {
        const real = readFileSync(COMPLETION_PLAN, "utf8");
        const banner = "> **Point-in-time snapshot (census taken 2026-08-10).**\n> The figures are NOT maintained; live: `node scripts/check-preflight-ci-parity.mjs`\n";
        return hasSnapshotBanner(real) &&
          hasSnapshotBanner(`# T\n\n${banner}\n## 1. x\n`) &&
          !hasSnapshotBanner("# T\n\n## 1. x\n") &&
          !hasSnapshotBanner(`# T\n\n${banner.replace("census taken 2026-08-10", "census taken recently")}\n## 1.\n`) &&
          !hasSnapshotBanner(`# T\n\n${banner.replace("`node scripts/check-preflight-ci-parity.mjs`", "the tree")}\n## 1.\n`) &&
          !hasSnapshotBanner(`# T\n\n## 1. x\n\n${banner}`) &&
          !hasSnapshotBanner(`# T\n\n${banner.replace("2026-08-10", "9999-99-99")}\n## 1.\n`) &&
          !hasSnapshotBanner(`# T\n\n<!--\n${banner}-->\n## 1.\n`) &&
          !hasSnapshotBanner(`# T\n\nbody\n\n${banner}`) &&
          !hasSnapshotBanner(`# T\n\n${banner.replace(" NOT maintained", "")}\n## 1.\n`);
      },
    },
    {
      name: "a lane declared in LANE_ENV but absent from package.json is NOT counted",
      run: () => liveLaneCount('const LANE_ENV = {\n  "proof:live-a": [],\n  "proof:live-b": [],\n};', { "proof:live-a": "x" }) === 1,
    },
  ];
  let bad = 0;
  for (const c of controls) {
    let ok = false;
    try { ok = !!c.run(); } catch { ok = false; }
    console.log(`  ${ok ? "ok  " : "FAIL"} — ${c.name}`);
    if (!ok) bad += 1;
  }
  console.log(`\nself-test: ${controls.length - bad}/${controls.length} controls passed`);
  process.exit(bad ? 1 : 0);
}

if (process.argv.includes("--self-test")) selfTest();
else main();
